  "d.109szp9": "שטח מוצק או מבנים שאפשר להתנגש בהם.",
  "d.10azxrl": "שלושה רדיוסי שמש מעל הפוטוספרה. הצל הוא חיים: מגן הפלטפורמה, השביט, הגופים הגדולים. התלקחויות מגיעות כל כמה דקות.",
  "d.10wlatv": "צבע מותאם אישית שהערוץ הבהיר ביותר שלו נמוך מ-0x40 נקרא כ-STOCK, כך שמגן לעולם אינו הופך לבלתי נראה.",
  "d.11cuwtu": "רקטות",
  "d.11jyj1n": "משחתת שנבנתה סביב תותח מסילה גבי בינוני, עם צריחי לייזר ושישה עשר תאי רקטות.",
  "d.11phsqq": "מו״ל משחקים שמתיר תוכן שנוצר 100% בבינה מלאכותית מפרסם את המשחק.",
  "d.11zjijr": "אפשר לפרוס ולהסיג כלי נשק (כלי נשק שהוסגו מוסתרים), והספינות כבר אינן משאירות אחריהן עשן.",
  "d.11zq7hg": "המראה: תאי טייס מוארים פיזיקלית, כוכבים מסווגים, ענק גזים בעל טבעות, רקע גלקסיה וערפילית, פלומות מנועים ואורות ניווט; תחושת המשחק של 0.1.0 ננעלה.",
  "d.12zyt91": "ANVIL, תמונת ההאנגר מתפריט המשחק (הגוף כפי שנבנה מ-0.3.0 ואילך; גודל מקורי 256 x 128). צילום מסך מתוך המשחק, גרסה 0.6.1",
  "d.13cb0px": "אויבים מעל העיר, עם פלומות מנועים (GLASGOW). צילום מסך מתוך המשחק, גרסה 0.5.3",
  "d.1436q76": "גרסה 0.5.1 הוקפאה: מושבי נקודות עיגון, מטחים של שש רקטות, ומפרץ ANVIL ששולח 10 NEEDLE.",
  "d.14s5uo6": "פלומות מנועים על ספינת קפיטל ועל מטוס קרב. צילום מסך מתוך המשחק, גרסה 0.5.3",
  "d.14vqvyw": "ה-ANVIL כשמפרץ ההאנגר שלו פתוח. צילום מסך מתוך המשחק, גרסה 0.6.1",
  "d.14zbb1f": "מטוס קרב קטן תחת אש של כנף עוינת בשדה האסטרואידים THETA-7, ובועת המגן שלו זוהרת.",
  "d.15oh132": "גרסאות מוקפאות",
  "d.16dme8w": "לייזרים קבועים מתכנסים לנקודת כיוון אחת מול הספינה.",
  "d.16sui9e": "ספינת דגל בגודל עיר, עם תוף מגורים מסתובב, שתי מסילות גביות כבדות ויער של תותחים.",
  "d.177y6xj": "האצה כפולה.",
  "d.178olkv": "המשחתת ANVIL כשדלת מפרץ ההאנגר שלה פתוחה ואור נשפך החוצה.",
  "d.17hv0ld": "אין כוח משיכה: נפילה חופשית.",
  "d.18fr12s": "מיירט",
  "d.18l8y3y": "נבנה עד כה בידי מייסד אחד.",
  "d.18qbnrf": "טריילר שנוצר בבינה מלאכותית מופק יחד עם יצירות אמנות שנוצרו בבינה מלאכותית.",
  "d.18qvzf2": "NEEDLE, תמונת ההאנגר מתפריט המשחק (הגוף כפי שנבנה מ-0.3.0 ואילך; גודל מקורי 256 x 128). צילום מסך מתוך המשחק, גרסה 0.6.1",
  "d.18yyc5": "מודולים נפגעים בנפרד והגוף מתפרק.",
  "d.194nnt6": "כלי סקר ארוך רגליים עם מכלים עטופים בנייר כסף, תורן חיישנים והרזרבה הגדולה ביותר להאצה.",
  "d.198svbo": "גרסה 0.5.0 הוקפאה: תאי טייס מוארים פיזיקלית, כוכבים מסווגים, ענק גזים בעל טבעות ורקע ערפילית.",
  "d.19i63zk": "ה-ORION-1 כפי שהוא מופיע בתפריט ההאנגר של המשחק, גוף מגרסה 0.6.1, מבט שלושת-רבעים על רקע שחור.",
  "d.19mf6u": "MERIDIAN, תמונת ההאנגר מתפריט המשחק (הגוף כפי שנבנה מ-0.3.0 ואילך; גודל מקורי 256 x 128). צילום מסך מתוך המשחק, גרסה 0.6.1",
